-- Refine untouched built-in defaults only; preserve all customized instructions.
UPDATE tags t SET description=CASE t.name WHEN 'Low' THEN 'No time-sensitive action remains; informational, resolved, or explicitly flexible request.' WHEN 'Medium' THEN 'Action is needed soon, but waiting until the next working day has no stated meaningful consequence.' WHEN 'High' THEN 'The conversation establishes that waiting until the next working day risks a missed commitment or material harm.' ELSE t.description END FROM tag_groups g WHERE t.group_id=g.id AND t.description='' AND g.name='Urgency' AND g.instructions='Assess how soon action is needed. Low: no time-sensitive action. Medium: action needed soon, but it can wait until the next working day. High: delaying until tomorrow has meaningful consequences. Do not infer urgency solely from emphatic language.' AND NOT g.enabled;
UPDATE tag_groups g SET instructions='Assess how soon our team must act on the latest unresolved request. Use earlier messages as context and account for confirmed responses and resolutions. Evaluate the consequence of delay independently of overall business impact. Emphatic wording alone does not establish urgency. Do not invent deadlines.',revision=revision+1,updated_at=now() WHERE g.name='Urgency' AND g.instructions='Assess how soon action is needed. Low: no time-sensitive action. Medium: action needed soon, but it can wait until the next working day. High: delaying until tomorrow has meaningful consequences. Do not infer urgency solely from emphatic language.' AND NOT g.enabled;
UPDATE tags t SET description=CASE t.name WHEN 'Low' THEN 'Routine or informational matter with limited evidenced customer or business impact.' WHEN 'Medium' THEN 'An unresolved issue affecting a customer relationship or ordinary business process, without evidence of major harm.' WHEN 'High' THEN 'Significant evidenced customer, business, or privacy consequences, such as a critical service failure, major loss, or exposed personal data.' ELSE t.description END FROM tag_groups g WHERE t.group_id=g.id AND t.description='' AND g.name='Importance' AND g.instructions='Assess customer and business impact independently of urgency. Low: routine or informational. Medium: affects a customer relationship or business process. High: significant customer, business or privacy consequences.' AND NOT g.enabled;
UPDATE tag_groups g SET instructions='Assess the customer or business impact of the latest unresolved issue independently of its deadline. Use only impact evidenced in the conversation. Do not infer customer value or high impact solely from the sender''s tone. Account for confirmed resolutions.',revision=revision+1,updated_at=now() WHERE g.name='Importance' AND g.instructions='Assess customer and business impact independently of urgency. Low: routine or informational. Medium: affects a customer relationship or business process. High: significant customer, business or privacy consequences.' AND NOT g.enabled;
